import type { Locator, Page } from '@playwright/test';
import { test, expect, demoOntology, settle, signIn, signInAsPersona, uniq } from './fixtures';

/**
 * Profile pictures. Simulated working-group members and demo testers get a bundled
 * picture (apps/web/public/avatars, generated by scripts/generate-avatars.mjs), so the
 * demo makes no third-party image requests. Anyone without a picture, or whose picture
 * fails to load, still shows their initials.
 */

/** The avatar's picture really loaded (not a broken image) and came from the bundled set. */
async function expectPicture(avatar: Locator) {
  await expect(avatar).toHaveAttribute('data-avatar', 'picture');
  const img = avatar.locator('img');
  await expect(img).toHaveAttribute('src', /^\/avatars\/(personas|demo)\/[\w-]+\.svg$/);
  await expect.poll(() => img.evaluate((el: HTMLImageElement) => el.complete && el.naturalWidth > 0)).toBe(true);
}

const membersList = (page: Page) => page.getByRole('list', { name: 'Members' });

test.describe('profile pictures', () => {
  test('simulated members show their own picture, not initials', async ({ page, request }) => {
    await signIn(page, { name: `Avatar viewer ${uniq()}`, role: 'contributor' });
    const demo = await demoOntology(request);
    await page.goto(`/o/${demo.id}`);
    await settle(page);

    const pictures: string[] = [];
    for (const name of ['Priya Shah', 'Tom Okafor', 'Aisha Rahman', 'Gareth Lewis', 'Mei Chen', 'Daniel Brooks']) {
      const avatar = membersList(page).getByRole('img', { name: `${name} (simulated)` });
      await expectPicture(avatar);
      await expect(avatar).not.toContainText(/\w/); // no initials alongside the picture
      pictures.push((await avatar.locator('img').getAttribute('src'))!);
    }
    // Everyone has a different face.
    expect(new Set(pictures).size).toBe(pictures.length);
  });

  test('a new tester gets a picture in the account menu, and keeps it', async ({ page }) => {
    const name = `Avatar tester ${uniq()}`;
    await signIn(page, { name, role: 'member' });
    await page.goto('/');
    await settle(page);
    const mine = page.locator('header').getByRole('img', { name, exact: true });
    await expectPicture(mine);
    const src = await mine.locator('img').getAttribute('src');

    await page.reload();
    await settle(page);
    await expect(page.locator('header').getByRole('img', { name, exact: true }).locator('img')).toHaveAttribute('src', src!);
  });

  test('the activity feed shows who acted with their picture', async ({ page }) => {
    await signInAsPersona(page, 'Tom Okafor');
    // Tom makes his own ontology, so his "created" entry is the newest in its feed. (This used to read the
    // shared demo ontology's feed, which shows only the latest three entries: once earlier specs' testers
    // had acted there, no simulated member was left in view and the test failed in the full suite.)
    const created = await page.request.post('/api/ontologies', { data: { title: `Avatar feed ${uniq()}`, prefix: 'avf', description: 'Activity feed pictures' } });
    expect(created.ok(), await created.text()).toBeTruthy();
    const { id } = (await created.json()) as { id: string };
    await page.goto(`/o/${id}`);
    await settle(page);
    // The feed used to pass only a name, so it always showed initials.
    const feed = page.getByRole('region', { name: 'Recent activity' });
    const tom = feed.getByRole('img', { name: 'Tom Okafor (simulated)' }).first();
    await expect(tom).toBeVisible();
    await expectPicture(tom);
  });

  test('falls back to initials when a picture cannot load', async ({ page, request, consoleGuard }) => {
    // The blocked images are logged as failed loads; that is the point of this test.
    consoleGuard.allow(/Failed to load resource/);
    await page.route('**/avatars/**', (route) => route.abort());
    const name = `Offline ${uniq()} Picture`;
    await signIn(page, { name, role: 'contributor' });
    const demo = await demoOntology(request);
    await page.goto(`/o/${demo.id}`);
    await settle(page);

    const priya = membersList(page).getByRole('img', { name: 'Priya Shah (simulated)' });
    await expect(priya).toHaveAttribute('data-avatar', 'initials');
    await expect(priya).toHaveText('PS');
    await expect(priya.locator('img')).toHaveCount(0);

    const mine = page.locator('header').getByRole('img', { name, exact: true });
    await expect(mine).toHaveAttribute('data-avatar', 'initials');
    await expect(mine).toHaveText('OP');
  });
});
